import React, { useRef, useState } from "react";
import { WHEPClient } from "red5pro-webrtc-sdk";

const WebRTCWHEPPlayer = () => {
  const videoRef = useRef(null);
  const subscriberRef = useRef(null);

  const [streamName, setStreamName] = useState("4CC382A86F88");
  const [status, setStatus] = useState("Status: Ready");
  const [isSubscribed, setIsSubscribed] = useState(false);

 const config = {
      protocol: 'ws',
      host: '104.236.58.81',
      port: 5080,
      app: 'live',
      streamName: '4CC382A86F88',
      rtcConfiguration: {
        iceServers: [{ urls: 'stun:stun2.l.google.com:19302' }]
      }
    };

 
  const startSubscribe = async () => {
    try {
      setStatus(`Status: Subscribing to "${streamName}"...`);


      const subscriber = new WHEPClient();
      subscriberRef.current = subscriber;

      subscriber.on("*", (event) => {
        console.log("[WHEP EVENT]", event.type);
      });

      await subscriber.init({
        ...config,
        mediaElementId: videoRef.current.id
      });

      await subscriber.subscribe();

      setStatus(`Status: Subscribed to "${streamName}"`);
      setIsSubscribed(true);
    } catch (e) {
      console.error(e);
      setStatus(`Status: Error - ${e.message}`);
    }
  };

  const stopSubscribe = async () => {
    try {
      if (subscriberRef.current) {
        await subscriberRef.current.unsubscribe();
        subscriberRef.current = null;
      }

      setStatus("Status: Stopped");
      setIsSubscribed(false);
    } catch (e) {
      console.error(e);
      setStatus(`Status: Error - ${e.message}`);
    }
  };

  return (
    <div style={{ padding: 20 }}>
      <h2>WebRTC WHEP Player</h2>

      <video
        id="sub-video"
        ref={videoRef}
        autoPlay
        playsInline
        muted
        style={{ width: 640, height: 480, background: "#000" }}
      />

      <div style={{ marginTop: 10 }}>
        <input
          value={streamName}
          onChange={(e) => setStreamName(e.target.value)}
          placeholder="Stream Name"
          style={{ padding: 8, marginRight: 8 }}
        />

        {!isSubscribed ? (
          <button onClick={startSubscribe}>Subscribe</button>
        ) : (
          <button onClick={stopSubscribe}>Stop</button>
        )}
      </div>

      <div style={{ marginTop: 10, fontFamily: "monospace" }}>
        {status}
      </div>
    </div>
  );
};

export default WebRTCWHEPPlayer;